// BatoScroll 1.0.0: middle-click autoscroll for Electron windows.
// GENERATED by scripts/build-embed.sh in github.com/BatoRoy/BatoScroll. Edit
// the sources there and re-vendor; don't edit this copy.
//
// Usage (main process):  require('./batoscroll').attach(win)
// Settings: ~/.config/bato/batoscroll.json, shared by every app and re-read
// on each page load. Missing keys use the defaults in settings.js below.
'use strict'

const { readFileSync } = require('fs')
const { join } = require('path')
const os = require('os')

const SETTINGS_PATH = join(os.homedir(), '.config', 'bato', 'batoscroll.json')

function readSettings() {
  try {
    return JSON.parse(readFileSync(SETTINGS_PATH, 'utf8'))
  } catch (err) {
    if (err.code !== 'ENOENT') console.error('BatoScroll: ignoring', SETTINGS_PATH, err.message)
    return {}
  }
}

// Runs in the page, never in Node: attach() stringifies it.
/* eslint-disable */
function page(config) {
(self.BatoScroll = self.BatoScroll || {}).embedded = true;
self.BatoScroll.config = config;

// BatoScroll — settings module
// Shared across the content script and the options page. Attaches a small API
// to window.BatoScroll.settings. Values are persisted in chrome.storage.sync.
(function () {
  "use strict";

  const NS = (self.BatoScroll = self.BatoScroll || {});
  if (NS.settings) return; // already loaded in this world

  const DEFAULTS = {
    deadZone: 10, // px radius around the origin where nothing scrolls
    sensitivity: 15, // velocity multiplier (distance px -> px/sec)
    maxSpeed: 15000, // px/sec cap, applied per axis
    indicatorSize: 44, // diameter of the compass, in px
    moveThreshold: 12, // travel (px) that flips hold-to-scroll vs click-toggle
    smoothing: 45, // velocity easing time constant (ms); 0 = instant response
    invert: false, // invert scroll direction
    excludes: [], // hostname patterns where BatoScroll stays off
  };

  const state = { values: { ...DEFAULTS }, loaded: false };

  function clampNum(value, min, max, fallback) {
    const n = Number(value);
    if (!Number.isFinite(n)) return fallback;
    return Math.min(max, Math.max(min, n));
  }

  function escapeRe(str) {
    return str.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }

  function normalize(raw) {
    const v = { ...DEFAULTS, ...(raw || {}) };
    v.deadZone = clampNum(v.deadZone, 0, 300, DEFAULTS.deadZone);
    v.sensitivity = clampNum(v.sensitivity, 1, 200, DEFAULTS.sensitivity);
    v.maxSpeed = clampNum(v.maxSpeed, 100, 40000, DEFAULTS.maxSpeed);
    v.indicatorSize = clampNum(v.indicatorSize, 20, 160, DEFAULTS.indicatorSize);
    v.moveThreshold = clampNum(v.moveThreshold, 2, 100, DEFAULTS.moveThreshold);
    v.smoothing = clampNum(v.smoothing, 0, 200, DEFAULTS.smoothing);
    v.invert = Boolean(v.invert);
    if (!Array.isArray(v.excludes)) {
      v.excludes =
        typeof v.excludes === "string"
          ? v.excludes.split(/[\n,]/)
          : [];
    }
    v.excludes = v.excludes
      .map((s) => String(s).trim().toLowerCase())
      .filter(Boolean);
    return v;
  }

  function matchHost(pattern, host) {
    if (!pattern) return false;
    pattern = String(pattern).trim().toLowerCase();
    if (!pattern) return false;
    host = (host || "").toLowerCase();
    // strip protocol / path if the user pasted a full URL
    pattern = pattern.replace(/^[a-z]+:\/\//, "").split("/")[0];
    if (pattern.includes("*")) {
      const re = new RegExp(
        "^" + pattern.split("*").map(escapeRe).join(".*") + "$"
      );
      return re.test(host);
    }
    return host === pattern || host.endsWith("." + pattern);
  }

  function isExcluded(host) {
    return (state.values.excludes || []).some((pat) => matchHost(pat, host));
  }

  // Outside an extension (embedded in an Electron app via dist/batoscroll.js)
  // there is no chrome.storage. The host reads the settings instead and hands
  // them over as NS.config before this file runs.
  const hasChromeStorage = (() => {
    try {
      return !!(self.chrome && chrome.storage && chrome.storage.sync);
    } catch (e) {
      return false;
    }
  })();

  function load() {
    if (!hasChromeStorage) {
      state.values = normalize(NS.config);
      state.loaded = true;
      return Promise.resolve(state.values);
    }
    return new Promise((resolve) => {
      try {
        chrome.storage.sync.get("settings", (res) => {
          if (chrome.runtime && chrome.runtime.lastError) {
            resolve(state.values);
            return;
          }
          state.values = normalize(res && res.settings);
          state.loaded = true;
          resolve(state.values);
        });
      } catch (e) {
        resolve(state.values);
      }
    });
  }

  function save(values) {
    const normalized = normalize(values);
    if (!hasChromeStorage) {
      // The host owns persistence; this only lasts until the next page load.
      state.values = normalized;
      return Promise.resolve(normalized);
    }
    return new Promise((resolve, reject) => {
      try {
        chrome.storage.sync.set({ settings: normalized }, () => {
          if (chrome.runtime && chrome.runtime.lastError) {
            reject(chrome.runtime.lastError);
            return;
          }
          state.values = normalized;
          resolve(normalized);
        });
      } catch (e) {
        reject(e);
      }
    });
  }

  // Keep every context in sync when settings change anywhere.
  if (hasChromeStorage) {
    try {
      chrome.storage.onChanged.addListener((changes, area) => {
        if (area === "sync" && changes.settings) {
          state.values = normalize(changes.settings.newValue);
        }
      });
    } catch (e) {
      /* storage not available in this context */
    }
  }

  NS.settings = {
    DEFAULTS,
    get: () => state.values,
    load,
    save,
    normalize,
    isExcluded,
  };
})();

// BatoScroll — the on-screen compass + capture overlay.
// Everything lives inside a Shadow DOM host so the page's CSS can never
// distort it. The host holds two layers:
//   1. a full-viewport overlay (captures the cursor, keeps the page inert,
//      shows the all-scroll cursor)
//   2. the compass itself (pointer-events: none, painted on top)
(function () {
  "use strict";

  const NS = (self.BatoScroll = self.BatoScroll || {});
  if (NS.Indicator) return;

  const HOST_ID = "batoscroll-host";

  class Indicator {
    constructor() {
      this.host = null;
      this.overlay = null;
      this.compass = null;
      this.arrows = {};
      this.size = 44;
      this.visible = false;
      this._dir = 0; // last direction bitmask, to skip no-op DOM writes
    }

    _dirMask(vx, vy) {
      return (vy < 0 ? 1 : 0) | (vy > 0 ? 2 : 0) | (vx < 0 ? 4 : 0) | (vx > 0 ? 8 : 0);
    }

    _build() {
      const host = document.createElement("div");
      host.id = HOST_ID;
      // Inline the critical positioning so a page can't override it via id.
      host.style.cssText =
        "all: initial; position: fixed; inset: 0; z-index: 2147483647;";
      const root = host.attachShadow ? host.attachShadow({ mode: "open" }) : host;

      const style = document.createElement("style");
      style.textContent = `
        :host { all: initial; }
        .overlay {
          position: fixed;
          inset: 0;
          cursor: all-scroll;
          background: transparent;
          /* captures pointer + wheel so the page stays inert while scrolling */
        }
        .compass {
          position: fixed;
          width: var(--sz, 44px);
          height: var(--sz, 44px);
          margin-left: calc(var(--sz, 44px) / -2);
          margin-top: calc(var(--sz, 44px) / -2);
          pointer-events: none;
          filter: drop-shadow(0 1px 3px rgba(0,0,0,0.45));
          animation: bato-pop 120ms ease-out;
        }
        @keyframes bato-pop {
          from { transform: scale(0.6); opacity: 0; }
          to   { transform: scale(1);   opacity: 1; }
        }
        .ring { fill: rgba(28,28,32,0.82); stroke: rgba(255,255,255,0.85); stroke-width: 2; }
        .dot  { fill: rgba(255,255,255,0.9); }
        .arrow { fill: rgba(255,255,255,0.55); transition: fill 60ms linear; }
        .arrow.active { fill: #4ea1ff; }
      `;

      const NSURI = "http://www.w3.org/2000/svg";
      const svg = document.createElementNS(NSURI, "svg");
      svg.setAttribute("class", "compass");
      svg.setAttribute("viewBox", "0 0 100 100");

      const ring = document.createElementNS(NSURI, "circle");
      ring.setAttribute("class", "ring");
      ring.setAttribute("cx", "50");
      ring.setAttribute("cy", "50");
      ring.setAttribute("r", "47");
      svg.appendChild(ring);

      // Four directional arrows as triangles around the centre.
      const defs = {
        up: "50,14 40,30 60,30",
        down: "50,86 40,70 60,70",
        left: "14,50 30,40 30,60",
        right: "86,50 70,40 70,60",
      };
      for (const [dir, points] of Object.entries(defs)) {
        const tri = document.createElementNS(NSURI, "polygon");
        tri.setAttribute("class", "arrow");
        tri.setAttribute("points", points);
        svg.appendChild(tri);
        this.arrows[dir] = tri;
      }

      const dot = document.createElementNS(NSURI, "circle");
      dot.setAttribute("class", "dot");
      dot.setAttribute("cx", "50");
      dot.setAttribute("cy", "50");
      dot.setAttribute("r", "5");
      svg.appendChild(dot);

      const overlay = document.createElement("div");
      overlay.className = "overlay";

      root.appendChild(style);
      root.appendChild(overlay);
      root.appendChild(svg);

      this.host = host;
      this.overlay = overlay;
      this.compass = svg;
    }

    show(x, y, size) {
      if (!this.host) this._build();
      if (typeof size === "number") this.size = size;
      this.compass.style.setProperty("--sz", this.size + "px");
      this.compass.style.left = x + "px";
      this.compass.style.top = y + "px";
      // restart the pop animation on each fresh activation
      this.compass.style.animation = "none";
      // force reflow so the animation can replay
      void this.compass.offsetWidth;
      this.compass.style.animation = "";
      this.setDirection(0, 0);
      const mount = document.documentElement || document.body;
      if (mount && this.host.parentNode !== mount) mount.appendChild(this.host);
      this.visible = true;
    }

    setDirection(vx, vy) {
      if (!this.arrows.up) return;
      // Called every animation frame; only write the DOM when the lit arrows
      // actually change, so a steady scroll doesn't invalidate style each tick.
      const mask = this._dirMask(vx, vy);
      if (mask === this._dir) return;
      this._dir = mask;
      this.arrows.up.classList.toggle("active", (mask & 1) !== 0);
      this.arrows.down.classList.toggle("active", (mask & 2) !== 0);
      this.arrows.left.classList.toggle("active", (mask & 4) !== 0);
      this.arrows.right.classList.toggle("active", (mask & 8) !== 0);
    }

    hide() {
      if (this.host && this.host.parentNode) {
        this.host.parentNode.removeChild(this.host);
      }
      this.visible = false;
    }
  }

  NS.Indicator = Indicator;
})();

// BatoScroll — content script (the engine).
//
// Behaviour, per the agreed design:
//   * Middle-click on a blank/non-interactive area drops a compass and arms
//     autoscroll. Links, buttons, form fields and editable regions are left
//     alone so new-tab / paste keep working.
//   * If you MOVE past a threshold before releasing the button, it's treated
//     as hold-to-scroll: releasing stops it.
//   * If you release without moving (a click), it stays in toggle mode:
//     move the mouse to scroll, click anywhere / Esc / wheel to stop.
//   * 2D, proportional speed (further from the compass = faster).
(function () {
  "use strict";

  const NS = (self.BatoScroll = self.BatoScroll || {});
  if (NS.__engineLoaded) return;
  NS.__engineLoaded = true;

  const settings = NS.settings;
  const indicator = new NS.Indicator();

  const STATE = { IDLE: 0, ARMED: 1, ACTIVE: 2 };
  const STOP_SWALLOW_MS = 250; // fallback teardown if no trailing click arrives
  const VEL_EPSILON = 0.5; // px/s — snap tiny residual velocity to rest

  const ctx = {
    state: STATE.IDLE,
    originX: 0,
    originY: 0,
    cursorX: 0,
    cursorY: 0,
    maxTravel: 0,
    scrollEl: null, // element to scroll, or null => scroll the window
    canX: false,
    canY: false,
    accX: 0, // sub-pixel scroll accumulators
    accY: 0,
    velX: 0, // smoothed velocity (px/sec), eased toward the target each frame
    velY: 0,
    cfg: null, // settings snapshot cached for the duration of a gesture
    rafId: null,
    lastTime: 0,
    suppressClick: false, // swallowing the gesture that stopped scrolling
    stopTimer: null,
  };

  const isEngaged = () => ctx.state !== STATE.IDLE || ctx.suppressClick;

  // ---- target eligibility --------------------------------------------------

  // On the web, middle-click on a link opens a new tab, so links and controls
  // are left alone. Inside an app (the embed build sets NS.embedded) nearly
  // every surface is a <button> and middle-click means nothing to them, so only
  // fields keep it (Linux middle-click paste). [data-batoscroll-ignore] lets an
  // app opt a widget out, e.g. a canvas that pans with the middle button.
  const INTERACTIVE_SELECTOR = NS.embedded
    ? "input, textarea, select, [contenteditable], [data-batoscroll-ignore]"
    : "a[href], button, input, textarea, select, option, label," +
      " audio, video, embed, object, summary, [role='button']," +
      " [role='link'], [contenteditable], [data-batoscroll-ignore]";

  function isEditable(el) {
    if (!el) return false;
    if (el.isContentEditable) return true;
    const tag = el.tagName;
    return tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT";
  }

  // The event's composedPath() is the full route it travelled, INCLUDING nodes
  // inside shadow trees. We must use it instead of event.target: a listener on
  // `window` sees `target` RETARGETED to the outermost shadow host, so on sites
  // built from web components (Reddit's entire UI) a middle-click on a link or
  // button reports the host custom element — which isn't a link — and the guard
  // below would miss it and arm autoscroll instead of opening the link.
  function eventPath(e) {
    if (typeof e.composedPath === "function") {
      const p = e.composedPath();
      if (p && p.length) return p;
    }
    return e.target ? [e.target] : [];
  }

  function isEligibleTarget(path) {
    for (const node of path) {
      if (!node || node.nodeType !== 1) continue; // skip text nodes, document, window
      if (isEditable(node)) return false;
      try {
        if (node.matches && node.matches(INTERACTIVE_SELECTOR)) return false;
      } catch (e) {
        /* malformed selector on exotic nodes — keep looking up the path */
      }
    }
    return true;
  }

  // ---- scroll container resolution ----------------------------------------

  function isScrollable(node) {
    if (!node || node.nodeType !== 1) return null;
    const cs = getComputedStyle(node);
    const oy = cs.overflowY;
    const ox = cs.overflowX;
    const canY =
      (oy === "auto" || oy === "scroll" || oy === "overlay") &&
      node.scrollHeight > node.clientHeight + 1;
    const canX =
      (ox === "auto" || ox === "scroll" || ox === "overlay") &&
      node.scrollWidth > node.clientWidth + 1;
    if (canX || canY) return { canX, canY };
    return null;
  }

  function resolveScrollTarget(target) {
    let node =
      target && target.nodeType === 1 ? target : target && target.parentElement;
    const root = document.documentElement;
    const body = document.body;
    while (node && node !== body && node !== root) {
      const s = isScrollable(node);
      if (s) {
        ctx.scrollEl = node;
        ctx.canX = s.canX;
        ctx.canY = s.canY;
        return true;
      }
      node =
        node.parentElement ||
        (node.getRootNode && node.getRootNode() instanceof ShadowRoot
          ? node.getRootNode().host
          : null);
    }
    // fall back to the document: window.scrollBy handles both axes. App
    // shells (React/Electron) often pin the document to the viewport and
    // scroll an inner panel instead; a middle-click outside that panel then
    // has nothing to scroll, so report that rather than drop a dead compass.
    const se = document.scrollingElement || root;
    ctx.scrollEl = null;
    ctx.canX = true;
    ctx.canY = true;
    return (
      !se ||
      se.scrollHeight > se.clientHeight + 1 ||
      se.scrollWidth > se.clientWidth + 1
    );
  }

  function doScroll(dx, dy) {
    // Relative scrollBy() with an explicit `behavior: "instant"`. Two reasons:
    //   1. "instant" overrides a page's CSS `scroll-behavior: smooth`, so our
    //      ~60 nudges/second aren't each animated (which stacks into lag).
    //   2. It never READS scrollTop/scrollLeft. Reading those forces a
    //      synchronous layout flush whenever the page's layout is dirty. On
    //      sites whose DOM mutates every frame (Reddit's feed lazy-loading
    //      media, changing element heights) that reflow 60×/sec is the jerk;
    //      the `+= ` form we used before paid it. Static pages (Wikipedia) kept
    //      layout clean, so they felt smooth either way.
    if (ctx.scrollEl) {
      const opts = { behavior: "instant" };
      if (ctx.canX && dx) opts.left = dx;
      if (ctx.canY && dy) opts.top = dy;
      if (opts.left || opts.top) ctx.scrollEl.scrollBy(opts);
    } else {
      self.scrollBy({ left: dx, top: dy, behavior: "instant" });
    }
  }

  // ---- velocity ------------------------------------------------------------

  function axisVelocity(delta) {
    const cfg = ctx.cfg || settings.get();
    const mag = Math.abs(delta);
    if (mag <= cfg.deadZone) return 0;
    const over = mag - cfg.deadZone;
    const v = Math.min(over * cfg.sensitivity, cfg.maxSpeed);
    const dir = cfg.invert ? -1 : 1;
    return Math.sign(delta) * v * dir;
  }

  // ---- animation loop ------------------------------------------------------

  function tick(now) {
    if (ctx.state === STATE.IDLE) {
      ctx.rafId = null;
      return;
    }
    const dt = Math.min((now - ctx.lastTime) / 1000, 0.05); // clamp long gaps
    ctx.lastTime = now;

    // Target velocity from the cursor's offset to the compass.
    const vx = axisVelocity(ctx.cursorX - ctx.originX);
    const vy = axisVelocity(ctx.cursorY - ctx.originY);
    indicator.setDirection(vx, vy);

    // Ease the applied velocity toward the target so speed changes and mouse
    // jitter feel smooth instead of snapping. Frame-rate independent: alpha is
    // derived from dt so the feel is identical at 60/120/144 Hz. tau comes from
    // the user's Smoothing setting (ms); 0 means snap straight to target.
    const tau = (ctx.cfg.smoothing || 0) / 1000;
    const alpha = tau > 0 ? 1 - Math.exp(-dt / tau) : 1;
    ctx.velX += (vx - ctx.velX) * alpha;
    ctx.velY += (vy - ctx.velY) * alpha;
    if (Math.abs(ctx.velX) < VEL_EPSILON) ctx.velX = 0;
    if (Math.abs(ctx.velY) < VEL_EPSILON) ctx.velY = 0;

    // Accumulate sub-pixel distance and emit whole *device* pixels, so slow
    // scrolling glides instead of stair-stepping on HiDPI / fractionally
    // scaled displays. On a 1x display this reduces to whole CSS pixels.
    ctx.accX += ctx.velX * dt;
    ctx.accY += ctx.velY * dt;
    const dpr = self.devicePixelRatio || 1;
    const stepX = Math.trunc(ctx.accX * dpr) / dpr;
    const stepY = Math.trunc(ctx.accY * dpr) / dpr;
    ctx.accX -= stepX;
    ctx.accY -= stepY;
    if (stepX || stepY) doScroll(stepX, stepY);

    ctx.rafId = requestAnimationFrame(tick);
  }

  function startLoop() {
    if (ctx.rafId != null) return;
    ctx.lastTime = performance.now();
    ctx.rafId = requestAnimationFrame(tick);
  }

  // ---- lifecycle -----------------------------------------------------------

  function arm(x, y, target) {
    if (!resolveScrollTarget(target)) return false;
    ctx.state = STATE.ARMED;
    ctx.originX = x;
    ctx.originY = y;
    ctx.cursorX = x;
    ctx.cursorY = y;
    ctx.maxTravel = 0;
    ctx.accX = 0;
    ctx.accY = 0;
    ctx.velX = 0;
    ctx.velY = 0;
    const cfg = (ctx.cfg = settings.get()); // snapshot for the whole gesture
    indicator.show(x, y, cfg.indicatorSize);
    document.documentElement.classList.add("batoscroll-active");
    startLoop();
    return true;
  }

  function clearStopTimer() {
    if (ctx.stopTimer != null) {
      clearTimeout(ctx.stopTimer);
      ctx.stopTimer = null;
    }
  }

  function stopScrolling() {
    ctx.state = STATE.IDLE;
    if (ctx.rafId != null) {
      cancelAnimationFrame(ctx.rafId);
      ctx.rafId = null;
    }
    indicator.setDirection(0, 0);
  }

  function teardownOverlay() {
    indicator.hide();
    document.documentElement.classList.remove("batoscroll-active");
    ctx.scrollEl = null;
  }

  // Stop scrolling immediately, no gesture to swallow (Esc, wheel, blur).
  function deactivate() {
    if (!isEngaged()) return;
    stopScrolling();
    clearStopTimer();
    ctx.suppressClick = false;
    teardownOverlay();
  }

  // Stop scrolling but keep the overlay up so the click/auxclick/contextmenu
  // that triggered the stop gets swallowed before it can reach the page.
  function beginStop() {
    stopScrolling();
    ctx.suppressClick = true;
    clearStopTimer();
    ctx.stopTimer = setTimeout(finalizeStop, STOP_SWALLOW_MS);
  }

  function finalizeStop() {
    clearStopTimer();
    ctx.suppressClick = false;
    teardownOverlay();
  }

  // ---- event handlers ------------------------------------------------------

  function onMouseDown(e) {
    if (ctx.suppressClick) {
      // mid-teardown from a previous stop; swallow stray presses
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (ctx.state === STATE.ACTIVE) {
      // any click while toggled-on stops (and is swallowed, so it can't
      // click through to a link/button underneath)
      e.preventDefault();
      e.stopPropagation();
      beginStop();
      return;
    }
    if (ctx.state !== STATE.IDLE) return; // ARMED: ignore extra presses
    if (e.button !== 1) return; // middle button only
    const path = eventPath(e);
    if (!isEligibleTarget(path)) return; // preserve link / paste behaviour
    if (settings.isExcluded(location.hostname)) return;

    // path[0] is the true innermost element (even inside shadow DOM); the
    // retargeted e.target would resolve the scroll container from the wrong node.
    if (!arm(e.clientX, e.clientY, path[0] || e.target)) return;
    e.preventDefault();
    e.stopPropagation();
  }

  function onMouseMove(e) {
    if (ctx.state === STATE.IDLE) return;
    ctx.cursorX = e.clientX;
    ctx.cursorY = e.clientY;
    if (ctx.state === STATE.ARMED) {
      const dx = e.clientX - ctx.originX;
      const dy = e.clientY - ctx.originY;
      ctx.maxTravel = Math.max(ctx.maxTravel, Math.hypot(dx, dy));
    }
  }

  function onMouseUp(e) {
    if (ctx.suppressClick) {
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (ctx.state !== STATE.ARMED) return;
    if (e.button !== 1) return; // only the middle-button release decides
    const cfg = settings.get();
    if (ctx.maxTravel > cfg.moveThreshold) {
      // moved while held => hold-to-scroll; releasing stops it. Swallow the
      // trailing auxclick so a link under the cursor doesn't open.
      beginStop();
    } else {
      // a clean click => stay live in toggle mode
      ctx.state = STATE.ACTIVE;
    }
  }

  function onClick(e) {
    if (ctx.suppressClick) {
      e.preventDefault();
      e.stopPropagation();
      finalizeStop();
    }
  }

  function onAuxClick(e) {
    if (ctx.suppressClick) {
      e.preventDefault();
      e.stopPropagation();
      finalizeStop();
      return;
    }
    // Swallow the auxclick that immediately follows entering toggle mode, so
    // it can't fire a stray new-tab; do NOT treat it as a stop.
    if (ctx.state !== STATE.IDLE && e.button === 1) {
      e.preventDefault();
      e.stopPropagation();
    }
  }

  function onContextMenu(e) {
    if (isEngaged()) {
      e.preventDefault();
      e.stopPropagation();
    }
  }

  function onKeyDown(e) {
    if (ctx.state !== STATE.IDLE && e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      deactivate();
    }
  }

  function onWheel() {
    // Manual scrolling is a clear signal the user wants control back.
    if (ctx.state !== STATE.IDLE) deactivate();
  }

  function onBlurOrHide() {
    if (isEngaged()) deactivate();
  }

  // Capture phase everywhere so we win before the page's own handlers.
  const cap = { capture: true };
  const capActive = { capture: true, passive: false };
  self.addEventListener("mousedown", onMouseDown, cap);
  self.addEventListener("mousemove", onMouseMove, cap);
  self.addEventListener("mouseup", onMouseUp, cap);
  self.addEventListener("click", onClick, cap);
  self.addEventListener("auxclick", onAuxClick, cap);
  self.addEventListener("contextmenu", onContextMenu, cap);
  self.addEventListener("keydown", onKeyDown, cap);
  self.addEventListener("wheel", onWheel, capActive);
  self.addEventListener("blur", onBlurOrHide);
  document.addEventListener("visibilitychange", () => {
    if (document.hidden) onBlurOrHide();
  });

  // Prevent text selection while a scroll is in progress.
  const selStyle = document.createElement("style");
  selStyle.textContent =
    ".batoscroll-active, .batoscroll-active * { user-select: none !important; -webkit-user-select: none !important; }";
  (document.head || document.documentElement).appendChild(selStyle);

  // Load persisted settings (defaults apply until this resolves).
  if (settings && settings.load) settings.load();
})();
}
/* eslint-enable */

const source = page.toString()

function attach(win) {
  const wc = win.webContents
  wc.on('dom-ready', () => {
    wc.executeJavaScript(`(${source})(${JSON.stringify(readSettings())})`).catch((err) => {
      console.error('BatoScroll: inject failed:', err)
    })
  })
}

module.exports = { attach, SETTINGS_PATH }
